# frozen_string_literal: true

module Anthropic
  module Models
    class FileNotDownloadableErrorDetails < Anthropic::Internal::Type::BaseModel
      # @!attribute error_code
      #
      #   @return [Symbol, :file_not_downloadable]
      required :error_code, const: :file_not_downloadable

      # @!method initialize(error_code: :file_not_downloadable)
      #   The file has `downloadable: false`. Only files generated by a tool, such as the
      #   code execution tool, can be downloaded.
      #
      #   @param error_code [Symbol, :file_not_downloadable]
    end
  end
end
